DO $$
DECLARE
  r record;
  n integer;
  total integer := 0;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('9c44529e-7fa6-4f8b-a635-1ab9de7b1986', '15194c4896e312d9ab5f239c767915f7', 'b5fd80301d5dfd1ab0f1a947c23d8e6d', $q$Чи може дитина їздити сама, чи має бути під наглядом?$q$, $q$Дитина завжди має бути під наглядом батька, матері або законного представника, який несе за неї повну відповідальність. Їзда дорогами загального користування заборонена.$q$),
    ('0b7ecebd-da89-44ec-ab2b-e3ac2063781b', '4275c9ff5661f57716b1ccb2c494928c', '1e0d958b046f092def29b37529adac7e', $q$Чи здасте мотоцикл і новачкові?$q$, $q$Так, здамо кожному, хто має чинне посвідчення водія відповідної категорії та чинну ID-картку або ПАСПОРТ. Мінімального досвіду не вимагаємо.$q$),
    ('ee1a5c2f-6eea-4db3-b012-b4d3d01ce0b6', 'ab752dbd7b1fabf76b927675a8cd951d', '65b0ebc02315d5b3458fc0cc9a7ff631', $q$Які розміри спорядження ви пропонуєте?$q$, $q$Усі доступні розміри вказані прямо у формі бронювання, де вибереш свій. Якщо не впевнений/-а щодо розміру, можеш приїхати приміряти одяг і черевики до нас у філію, але, будь ласка, повідом нам заздалегідь.&nbsp;<div><br><div>Доступні розміри:&nbsp;</div><div>Дорослі:</div><div>Шолом — XS–3XL</div><div>Куртка — S–6XL (філія самообслуговування Velké Němčice: до 4XL)</div><div>Штани — M–6XL (філія самообслуговування Velké Němčice: до 4XL)</div><div>Рукавиці — M–3XL</div><div><br></div><div>Діти:</div><div>Шолом: YM, XS, S</div><div>Куртка: YM (4–6 років) або захисний жилет і джерсі (4–9 років)</div><div>Рукавиці: 4–12 років</div><div>Штани: 4–9 років</div></div>$q$),
    ('310136c2-cf0c-417e-aada-029b525c47c0', 'c2a2cfedee58c7a366e411e5be83b668', '53fbd2ed4a33960c9fe8110e24915a7c', $q$Чи можна орендувати й мотоботи?$q$, $q$Так, мотоциклетні черевики пропонуємо як додаткову платну послугу — для водія і для пасажира. Просто додай їх у формі бронювання. Для дорослих пропонуємо розміри 39–48, для дітей поки що черевики розмірів 33 і 35. Пропозицію поступово розширюватимемо.&nbsp;$q$),
    ('4975240d-08a4-458b-9a21-3ec8fb9557b1', '531ef39eb3001d1a9ea46b61f7baf171', '30e1c70081cc54e0a8956a4547e38e07', $q$Чи мають мотоцикли кофри?$q$, $q$Залежить від типу мотоцикла. Туристичні мотоцикли зазвичай мають 3 кофри, нейкеди й супермото — 1 кофр або сумку на бак. Дитячі мотоцикли кофрів не мають. Якщо мотоцикл має кофри, вони завжди є його невід’ємною частиною, і ти нічого за них не платиш. Точне оснащення кожного мотоцикла знайдеш у каталозі в описі моделі.&nbsp;$q$),
    ('d2051db9-f4d6-4d24-9009-c3df6be6fd45', '4538b22cf3e2b9324293521760089d35', 'b34b15667034ab02543eea4a0c942520', $q$Чи можете ви доставити мотоцикл до готелю чи на вокзал?$q$, $q$Так, мотоцикл доставимо в домовлене місце в межах Чехії. Ціна складається з плати за завантаження й розвантаження (2 × 500 Kč) і ставки 20 Kč/км — рахуємо кілометри туди й назад від Mezná біля Пельгржимова.$q$),
    ('8e69d06c-f810-46e9-980f-fa69865d25af', '219bbca6689427cb6fd1971bfe0f6f43', '9577a25089ad59f373d30abd104c0a95', $q$Як замовити доставку?$q$, $q$Просто — під час онлайн-бронювання вкажеш адресу й час доставки. Ціна розрахується автоматично.$q$),
    ('59befbaa-6b5d-4188-80cc-6a67c08b1e3c', '9c0c120219cf431ed465d6abc93dcebd', '3158f4a4c01d6976bf8fb6c55325fa8f', $q$Як далеко ви доставляєте мотоцикли?$q$, $q$Доставляємо по всій Чеській Республіці, доставки за кордон не пропонуємо.$q$),
    ('178523b3-1d4f-4f8c-a8dd-32df04cb2431', '8d8d9b43b8f5bccf545369f89a4e551a', '8d766a26640be16cd2a74e9694b38993', $q$Як відбувається отримання мотоцикла під час доставки в інше місце?$q$, $q$Ми приїдемо в домовлене місце в погоджений час. Привеземо тобі мотоцикл і спорядження, яке ти вибрав/-ла під час бронювання. Разом оглянемо мотоцикл, перевіримо твої документи, підпишемо акт приймання-передачі, і ти отримаєш ключі та інструкції.$q$),
    ('d87bbb0e-0cc1-43a0-9cc4-9a2dc3118aac', 'b2f669456a2af48a0285777b976f075a', '4088fbb48797352dcf857a0732e0c445', $q$Хто платить штраф або правопорушення, скоєне під час оренди?$q$, $q$<p>Усі <strong>дорожні штрафи, правопорушення та адміністративні проступки</strong>, скоєні під час строку оренди, у повному обсязі оплачує орендар. Якщо штраф надійде нам як власнику транспортного засобу, ти зобов’язуєшся негайно його сплатити — або ж ми маємо право передати твої дані відповідним органам, щоб відповідальність за правопорушення перейшла на тебе.</p>
<p>Так само орендар сам оплачує <strong>віньєтки, плату за платні дороги й паркування</strong> в Чехії та за кордоном; ми їх за тебе не оплачуємо й не фінансуємо наперед.</p>$q$),
    ('90382ead-fb70-4aed-9379-3d2cb872dda5', '92e7aa740dae965f0ef3c3a7ff1044d4', '0e429360697c5c34d9c0c0ebb6f5ae29', $q$Ви здаєте щось і для категорії A1?$q$, $q$Так. Тепер у нас є скутери, якими можна керувати з категорією A1 або навіть лише з B. Автопарк постійно розширюємо, і найближчим часом плануємо додати мотоцикли категорії A1.&nbsp;$q$),
    ('822fd461-7ba5-44ee-84c8-c728cf085656', '67a305f8aaff1cdd6ca7b2655b42bd47', 'a783f0e5daa4bca6432c6557a1366fed', $q$<strong>Чи є знижка за отримання після обіду?</strong><br>$q$, $q$<p>Так. Якщо через брак часу ти не можеш забрати мотоцикл зранку, надаємо знижку 50 % на перший день оренди за отримання о 12:00 і пізніше. Знижка діє для бронювань на 2 й більше днів і автоматично врахується у формі бронювання.&nbsp;</p>$q$),
    ('dd96d6c9-3b64-47b1-94aa-e9848d7777ac', '8cf76797fb0234bf02225b0ade8fe00c', '506ea45a7d5b9e4e866a703b2902b4f8', $q$Хто підписує договір за дитину?$q$, $q$Договір підписує <span style="font-weight: bold;">батько, мати </span>або <span style="font-weight: bold;">законний представник</span>, який водночас буде вказаний як орендар.$q$),
    ('9446abc2-3308-484f-b255-bc425f3d3d52', '0cbcd1b9625d486286d2251271b3c72a', '7878a19cd75dd81239c861fb0d8ec563', $q$Яке посвідчення водія мені потрібне?$q$, $q$Залежить від того, який мотоцикл ти обереш — у кожної моделі прямо в пропозиції вказано, яка категорія посвідчення водія потрібна. Потужніші мотоцикли вимагають категорії A, слабші — категорії A2. Для дитячих мотоциклів посвідчення водія не потрібне.$q$),
    ('424453f2-03d2-4929-a6b7-0714cc19382d', '82e5657833662781da70b04d42a141cb', '11c29991c57ac6d70b1683c5dea9ff93', $q$Чи можу я скасувати бронювання або змінити дату?$q$, $q$Так, <span style="font-weight: bold;">безкоштовне скасування бронювання&nbsp; </span>можливе <span style="font-weight: bold;">не пізніше ніж за 7 днів до погодженого терміну </span>отримання мотоцикла.&nbsp;<div>У разі скасування бронювання за 2–7 днів до початку оренди ми можемо стягнути плату за скасування до 50 % погодженої орендної плати.</div><div>У разі скасування бронювання менш ніж за 2 дні до початку оренди ми залишаємо за собою право стягнути повну орендну плату. Якщо ти не забереш мотоцикл без попереднього скасування бронювання, ми так само стягуємо повну орендну плату.&nbsp;</div><div>Зміну дати вирішуй якнайшвидше в розділі&nbsp;<span style="font-weight: bold;">Змінити бронювання </span>прямо на нашому сайті. Або зв’яжися з нами.</div>$q$),
    ('eb9da018-552b-4c67-a224-e7b116c0c55f', '4da24a2846bb562689d7f416004c5baf', 'b0e24ccc25fc8f7d5ba474eb6e4b4cf2', $q$Чи можна заплатити під час отримання мотоцикла?$q$, $q$Ні, оплата відбувається виключно онлайн під час завершення бронювання. Без успішної оплати бронювання не створюється. Готівку не приймаємо.&nbsp;$q$),
    ('1f0e38c0-35a8-4737-93ba-bde974234a9e', '9d055e59a2e929d5de2fb69e105c489b', '3e8ee689810fb5bcfbbc3a1136c0291e', $q$Чи можна поїхати й за межі ЄС?$q$, $q$Так, <span style="font-weight: bold;">можна</span> <span style="font-weight: bold;">вирушити </span>і до <span style="font-weight: bold;">країн за межами ЄС</span>. Потрібно лише дотримуватися територіальної дії зеленої карти через обов’язкове страхування цивільної відповідальності.&nbsp;$q$),
    ('e9d26f91-d0b8-4578-b586-f581d95cc67a', 'd9bf4e38623a2d45edd464323ef1dad8', '1205f9a6e62379a07181a5a7fd0298e3', $q$Чи потрібно мені думати про віньєтки й плату за дороги?$q$, $q$<p>У Чехії мотоциклам віньєтка <strong>не потрібна</strong> — за законом вони звільнені від плати за автомагістралі. За кордоном, однак, можуть діяти інші правила (плата за дороги, віньєтки, міські збори). Усі <strong>віньєтки, плату за дороги, паркування та подібні збори в Чехії й за кордоном оплачує орендар</strong> — ми їх не оплачуємо й не фінансуємо наперед.</p>$q$),
    ('b0f644e0-643d-495f-b6db-7a752c02cbeb', '8f132536deee1652123406590c02ea3b', 'd49e2135724e5a608a4fde4ae50b9496', $q$Чи можна поїхати з мотоциклом за кордон?$q$, $q$Так, з мотоциклом можна без проблем вирушити й за кордон. Поїздки за межі Чехії ми не обмежуємо, потрібно лише дотримуватися територіальної дії страхування (зелена карта).<br>Страхування не поширюється на Білорусь, Іран, Росію, Сербію та Кіпр — тому їзда до цих країн заборонена.$q$),
    ('bc998060-a598-433c-acc3-f0f03c32ca14', 'e7a097dacb5e093814b54a61217ce862', 'ca91d033c1fd2ec167463223c65cc761', $q$Чи потрібне щось особливе для поїздки за кордон?$q$, $q$Нічого особливого — техпаспорт і зелена карта входять до комплекту мотоцикла. Радимо мати при собі <strong>договір оренди</strong>, який ми автоматично надішлемо тобі на e-mail після створення та оплати бронювання.&nbsp;<div>Договір оренди підтверджує правомірне користування транспортним засобом у разі поліцейської перевірки. Також радимо оформити туристичне страхування.</div>$q$),
    ('921f40e1-9bfd-4a5e-b8a4-b6afcb7f5b94', '60596038ff1eafdb53327fa6c88849e4', '8e5fd47f0eecc1104523e07789aeeddf', $q$Чи є мінімальний номінал подарункового сертифіката?$q$, $q$Так, <span style="font-weight: bold;">мінімальний номінал </span>сертифіката — <span style="font-weight: bold;">100 </span>Kč.&nbsp;$q$),
    ('780628c8-34ab-4a86-96da-2b46f5529594', '34b1257a345d47c44e9d9782b451efe9', 'ec346c572bf68d0dfcfe7d5b3308a038', $q$Чи можна замовити сертифікат на компанію?&nbsp;$q$, $q$Так, можна. Під час замовлення сертифіката просто заповни також <span style="font-weight: bold;">поля Компанія </span>та <span style="font-weight: bold;">IČO</span>. Після оплати разом із подарунковим сертифікатом ми надішлемо тобі електронною поштою і підтвердження про отриману оплату.&nbsp;$q$),
    ('c4bdc76c-4037-488b-a46d-7e15c3697664', 'a31cf38568226477a3709066018936e5', 'fdfd5943a96e65c5295334f2fe07f6ae', $q$Як обдарований використає сертифікат?$q$, $q$Обдарований бронює мотоцикл онлайн у формі бронювання.<span style="font-weight: bold;"> У&nbsp; полі Знижковий код</span>/<span style="font-weight: bold;">Подарунковий сертифікат він вводить свій унікальний код із ваучера, який отримав.&nbsp;</span>$q$),
    ('745b52dd-712d-4bb8-b1ca-65204ef49b90', '4ec205274cb78a806631ca01738d9126', '78b3e91c48f01710f4a6ce965fd3c097', $q$<strong>Я купив/-ла сертифікат MotoGo24 на Slevomat, як його використати?</strong><br>$q$, $q$<blockquote><p>Просто — термін, мотоцикл і все інше обереш прямо на нашому сайті (натиснеш кнопку ЗАБРОНЮВАТИ). У формі бронювання заповниш усі потрібні дані, а сертифікат використаєш у полі <span style="font-weight: bold;">Знижковий код/подарунковий сертифікат.&nbsp;</span>Достатньо ввести його код.&nbsp;</p></blockquote>$q$),
    ('2c128ed9-e685-46be-b290-8b0d1f33d8f7', '99f4b2be7a9110379298f87a32e90e18', 'eeb048653acf8c080de489df4599927e', $q$Коли можна використати отриманий сертифікат?$q$, $q$Сертифікат можна використати <span style="font-weight: bold;">будь-коли</span>. Він <span style="font-weight: bold;">не </span>має жодних <span style="font-weight: bold;">обмежень</span> на міжсезоння чи окремі дати.$q$),
    ('78d4791f-d161-41eb-b754-6a3c732f2ea6', '4b866ee054dd9da5cf810e9d484e5368', 'e168844bdb30def69a74b94fcebab615', $q$Чи можна використати подарунковий сертифікат для покупки у вашому інтернет-магазині?$q$, $q$Ні, на жаль, це неможливо. Подарункові сертифікати MotoGo24 і сертифікати, придбані через Slevomat, не можна використати в інтернет-магазині — вони призначені лише для враження, тобто орендувати мотоцикл і вирушити навперегони з вітром. В інтернет-магазині можна використати лише знижковий (промо) код, і його не можна застосувати до покупки подарункового сертифіката.$q$),
    ('1c13a6d0-0756-46ba-ae1f-761f2c837ca9', '646e80fbbd2609c812768bcd2ea243e1', 'c2c68db40e6eb559904465d173a437e5', $q$Який строк дії подарункового сертифіката?$q$, $q$<strong>3 роки</strong> з дати видачі. Термін оренди мотоцикла обдарований обирає сам через нашу систему бронювання відповідно до поточної доступності.$q$),
    ('59c0e244-3654-4d59-9398-a287ca612c72', '3381812aab45298e9e6a1b5930f35bbb', '3c47ce454f38df54784ea403bb48751c', $q$На які мотоцикли можна використати сертифікат?$q$, $q$На всі мотоцикли з нашого каталогу.$q$),
    ('56e73a47-b8eb-4e95-8dfd-e86993cb23ab', 'f4afb6de2947b36bd5bd5d02be9fdd57', '96b625f43f866fd2ae4112ecf442fb75', $q$Чи має обдарований платити заставу?$q$, $q$<strong>Ні, жодної застави не потрібно.</strong> Наші умови прозорі, а спорядження для водія завжди входить у ціну.$q$),
    ('0687d883-0734-4a1a-8b26-0df13185df1d', '3d5a0ef440fd848d1285309b5aded306', '33f312760a0db49329e843ddae785b2d', $q$Як ви доставите ваучер?$q$, $q$<strong>Одразу електронною поштою</strong> після оплати (PDF). Якщо ти вибрав/-ла друкований подарунковий сертифікат, надішлемо його якнайшвидше Чеською поштою.&nbsp;$q$),
    ('fe21099d-7b78-4eb6-bfb7-78e854e8ba0a', 'baf39a1606de518f4528b7bb3387f557', 'a53215c1a9025a314af95e6007742601', $q$Чи можна змінити дату використання?$q$, $q$Так, дату можна змінити, якщо мотоцикл у бажаний тобою день вільний. Керувати бронюванням можеш сам у розділі <span style="font-weight: bold;">Змінити бронювання </span>прямо тут, на сайті (значок олівця на верхній панелі).&nbsp;$q$)
  ) AS v(id, q_md5, a_md5, q_uk, a_uk) LOOP
    UPDATE public.faq_items
       SET translations = COALESCE(translations, '{}'::jsonb) || jsonb_build_object('uk', jsonb_build_object('question', r.q_uk, 'answer', r.a_uk))
     WHERE id = r.id::uuid AND md5(question) = r.q_md5 AND md5(answer) = r.a_md5
       AND NOT (COALESCE(translations, '{}'::jsonb) ? 'uk');
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    IF n = 0 THEN RAISE NOTICE 'faq uk: beze změny % (uk už je, nebo se čeština změnila)', r.id; END IF;
  END LOOP;
  RAISE NOTICE 'faq uk (část 2): doplněno % překladů', total;
END $$;
